// Gate - the same X-Munshiji-Token check as the actions workflow, with one difference: the
// schedule trigger has no HTTP request at all, so there are no headers to check. Only a run
// that came in through the webhook has to prove who it is.
if ($json.headers !== undefined) {
  const expected = $vars.MUNSHIJI_TOKEN || '';
  const incoming = $json.headers?.['x-munshiji-token'] || '';
  if (expected && incoming !== expected) {
    throw new Error('unauthorised: X-Munshiji-Token did not match');
  }
}

return [{ json: { requested_at: new Date().toISOString() } }];

// One message in the merchant's own language. Everything here arrived from the four fetches
// upstream, so a failure in this node is a formatting bug, never a data one.
const merchant = $('Fetch merchant').first().json;
const dash = $('Fetch dashboard').first().json;
const insights = $('Fetch insights').first().json.insights ?? [];
const actions = $('Fetch pending actions').first().json.actions ?? [];

const hi = (merchant.language || 'hi') === 'hi';
const today = dash.today ?? {};
const insight = insights[0] ?? null;
const action = actions[0] ?? null;

const lines = [];
if (hi) {
  lines.push(`🌆 शाम का हिसाब — ${merchant.shop_name}`);
  lines.push('');
  lines.push(`आज की वसूली: ${today.collected?.display ?? '₹0'} (${today.transactions ?? 0} लेन-देन, ${today.unique_customers ?? 0} ग्राहक)`);
  if (today.projected_close) {
    lines.push(`अनुमानित क्लोज़: ${today.projected_close.display}`);
  }
  lines.push(`खुला उधार: ${dash.open_udhaar?.display ?? '₹0'} (${dash.open_udhaar_count ?? 0} खाते)`);
  if (insight) {
    lines.push('');
    lines.push(`आज की सबसे बड़ी बात: ${insight.title_hi || insight.title_en}`);
  }
  if (action) {
    lines.push('');
    lines.push(`एक काम रुका है: ${action.summary_hi || action.summary_en}`);
    lines.push('भेज दूँ?');
  }
} else {
  lines.push(`🌆 Shaam ka Hisaab — ${merchant.shop_name}`);
  lines.push('');
  lines.push(`Collected today: ${today.collected?.display ?? '₹0'} (${today.transactions ?? 0} transactions, ${today.unique_customers ?? 0} customers)`);
  if (today.projected_close) {
    lines.push(`Projected close: ${today.projected_close.display}`);
  }
  lines.push(`Open udhaar: ${dash.open_udhaar?.display ?? '₹0'} (${dash.open_udhaar_count ?? 0} khatas)`);
  if (insight) {
    lines.push('');
    lines.push(`Biggest thing today: ${insight.title_en}`);
  }
  if (action) {
    lines.push('');
    lines.push(`One thing is waiting: ${action.summary_en || action.summary_hi}`);
    lines.push('Send it?');
  }
}

return [{ json: {
  digest: lines.join('\n'),
  action_id: action ? action.id : null,
  language: merchant.language || 'hi',
} }];
